  if (type === 'volto') return s+`<ellipse class="shadow" cx="112" cy="199" rx="63" ry="10"/><path class="accent" d="M123 20 85 97h25l-9 49 43-72h-27z"/><path class="body" d="M50 98c0-35 25-58 61-58s60 24 60 59v49c0 36-25 51-61 51s-60-15-60-51z"/><path class="stroke" d="M51 128 28 148m141-20 24 16M80 183l-10 22m71-22 10 22"/><path class="accent" d="m71 92 17-12 8 20-17 10zm57-10 18 11-10 19-17-11z"/><ellipse class="eye" cx="89" cy="117" rx="7" ry="10"/><ellipse class="eye" cx="133" cy="117" rx="7" ry="10"/><path class="thin" d="M91 146q19 12 38-1"/><circle class="spark" cx="92" cy="114" r="2"/><circle class="spark" cx="136" cy="114" r="2"/></svg>`;
  if (type === 'curro') return s+`<ellipse class="shadow" cx="110" cy="199" rx="66" ry="10"/><path class="accent" d="M51 99Q18 110 34 140q14 23 43 3"/><path class="body" d="M54 98c0-36 22-59 57-59 43 0 62 31 58 73-4 46-26 83-66 83-33 0-55-24-52-66z"/><path class="stroke" d="m59 151-30 23m137-12 26 20M79 185l-7 20m63-20 8 20"/><path class="accent" d="M74 79q38-27 78 1-12-45-42-44-28 1-36 43z"/><ellipse class="eye" cx="91" cy="119" rx="7" ry="10"/><ellipse class="eye" cx="131" cy="119" rx="7" ry="10"/><path class="thin" d="M91 148q20 17 40-1"/><path class="thin" d="M54 62q-20-20-15-40m88 15q16-18 11-35"/><circle class="spark" cx="93" cy="116" r="2"/><circle class="spark" cx="134" cy="116" r="2"/></svg>`;
