  return s+`<ellipse class="shadow" cx="110" cy="199" rx="63" ry="10"/><path class="accent" d="m108 14 9 26 28-5-20 21 18 21-31-4-11 27-7-29-29 1 20-21-17-22 29 7z"/><path class="body" d="M52 101q0-55 58-55t58 55v48q0 47-58 47t-58-47z"/><path class="stroke" d="m54 127-29 16m142-15 29 14M82 187l-8 18m64-18 8 18"/><path class="accent" d="M67 91q17-25 39-13 22-14 46 8l-7-34q-34-24-70 0z"/><ellipse class="eye" cx="88" cy="124" rx="7" ry="10"/><ellipse class="eye" cx="132" cy="124" rx="7" ry="10"/><path class="thin" d="M89 151q22 21 42-2"/><path class="thin" d="m46 83-18-10m148 8 17-11"/><circle class="spark" cx="91" cy="121" r="2"/><circle class="spark" cx="135" cy="121" r="2"/></svg>`;
