function footer() { return `<footer class="footer"><div class="footer-inner"><div><a href="#/" class="brand"><span class="brand-mark">N</span><span><strong>NAMMA</strong><em>CIRCUIT UNIVERSE</em></span></a><p class="footer-tagline">Making electronics less scary, one circuit at a time.</p></div><div><h3>Explore</h3><a href="#/universe">The Universe</a><a href="#/learn">Learn with NCU</a><a href="#/characters">Circuit Crew</a><a href="#/stories">NCU Stories</a></div><div><h3>Build</h3><a href="#/lab">Interactive Lab</a><a href="#/formulas">Formula Lab</a><a href="#/quizzes">Circuit Quiz</a><a href="#/learn/microcontrollers">NCU Lab</a></div><div><h3>Keep in touch</h3><a href="${instagramUrl}" target="_blank" rel="noopener">@namma.circuit ↗</a><a href="mailto:hello@nammacircuit.com">Contact NCU</a><a href="#/privacy">Privacy</a><a href="#/terms">Terms</a></div></div><div class="footer-bottom"><span>© 2026 Namma Circuit Universe. Built with curiosity.</span><a href="#/">Back to home ↑</a></div></footer>`; }

function heading(eyebrow, title, text, link) { return `<div class="section-heading"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div>${text ? `<div><p>${text}</p>${link || ''}</div>` : ''}</div>`; }

function crewCard(key) { const c=characters[key]; return `<article class="crew-card" style="--card-color:${c.color}"><div class="crew-art"><span class="crew-label">${c.label}</span>${mascot(key)}</div><div class="crew-content"><h3>${c.name}</h3><div class="concept">${c.concept.toUpperCase()}</div><p>${c.personality}</p></div><div class="crew-card-footer"><button class="text-button" data-route="/characters/${key}">Meet ${c.name}<span>→</span></button><span class="chip" style="--chip-color:${c.color}">${c.lessons.length} lessons</span></div></article>`; }

