  <section class="section grid-backdrop" id="crew">${heading('The cast of the circuit', 'MEET THE<br>CIRCUIT CREW', 'Not textbook diagrams. Actual personalities you will remember when the exam gets serious.', '<a class="section-link" href="#/characters">MEET THE FULL CREW →</a>')}<div class="crew-grid">${Object.keys(characters).map(crewCard).join('')}</div></section>
